#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> filterRestaurants(std::vector<std::vector<int>>& restaurants, int veganFriendly, int maxPrice, int maxDistance) {
        std::vector<std::vector<int>> filtered;
        for (const auto& r : restaurants) {
            if ((!veganFriendly || r[2] == 1) && r[3] <= maxPrice && r[4] <= maxDistance) {
                filtered.push_back(r);
            }
        }
        std::sort(filtered.begin(), filtered.end(), [](const auto& a, const auto& b) {
            if (a[1] != b[1]) return a[1] > b[1];
            return a[0] > b[0];
        });
        std::vector<int> res;
        for (const auto& r : filtered) res.push_back(r[0]);
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> filterRestaurants(int[][] restaurants, int veganFriendly, int maxPrice, int maxDistance) {
        List<int[]> filtered = new ArrayList<>();
        for (int[] r : restaurants) {
            if ((veganFriendly == 0 || r[2] == 1) && r[3] <= maxPrice && r[4] <= maxDistance) {
                filtered.add(r);
            }
        }
        filtered.sort((a, b) -> {
            if (a[1] != b[1]) return Integer.compare(b[1], a[1]);
            return Integer.compare(b[0], a[0]);
        });
        List<Integer> res = new ArrayList<>();
        for (int[] r : filtered) res.add(r[0]);
        return res;
    }
}

var filterRestaurants = function(restaurants, veganFriendly, maxPrice, maxDistance) {
    const filtered = restaurants.filter(r => {
        return (!veganFriendly || r[2] === 1) && r[3] <= maxPrice && r[4] <= maxDistance;
    });
    filtered.sort((a, b) => {
        if (a[1] !== b[1]) return b[1] - a[1];
        return b[0] - a[0];
    });
    return filtered.map(r => r[0]);
};
